SELECT * FROM sales_product WHERE organization_id=#{org}
AND active=#{active}
AND (sku ILIKE CONCAT('%',#{query},'%') OR name ILIKE CONCAT('%',#{query},'%'))
ORDER BY updated_at DESC,id

SELECT p.id,p.sku,p.name,p.unit,p.tax_rate,p.active,COALESCE(e.unit_price,p.list_price) AS list_price
FROM sales_product p LEFT JOIN sales_price_entry e ON e.organization_id=p.organization_id AND e.product_id=p.id AND e.price_book_id=#{book,jdbcType=OTHER}
WHERE p.organization_id=#{org} AND p.active=true AND p.id IN
#{id}
AND e.product_id IS NOT NULL
